    return IO.Schema(node_id='ClaudeNode', display_name='Anthropic Claude', category='partner/text/Anthropic', essentials_category='Text Generation', description="Generate text responses with Anthropic's Claude models. Provide a text prompt and optionally one or more images for multimodal context.", inputs=[IO.String.Input('prompt', multiline=True, default='', tooltip='Text input to the model.'), IO.DynamicCombo.Input('model', options=[IO.DynamicCombo.Option(label, _claude_model_inputs(label)) for label in CLAUDE_MODELS], tooltip='The Claude model used to generate the response.'), IO.Int.Input('seed', default=0, min=0, max=2147483647, control_after_generate=True, tooltip='Seed controls whether the node should re-run; results are non-deterministic regardless of seed.'), IO.Autogrow.Input('images', template=IO.Autogrow.TemplateNames(IO.Image.Input('image'), names=[f'image_{i}' for i in range(1, CLAUDE_MAX_IMAGES + 1)], min=0), tooltip=f'Optional image(s) to use as context for the model. Up to {CLAUDE_MAX_IMAGES} images.'), IO.String.Input('system_prompt', multiline=True, default='', optional=True, advanced=True, tooltip="Foundational instructions that dictate the model's behavior.")], outputs=[IO.String.Output()], hidden=[IO.Hidden.auth_token_comfy_org, IO.Hidden.api_key_comfy_org, IO.Hidden.unique_id], is_api_node=True, price_badge=IO.PriceBadge(depends_on=IO.PriceBadgeDepends(widgets=['model']), expr='
